import { beforeEach, describe, it, expect, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  auth: vi.fn(),
  user: vi.fn(),
  limit: vi.fn(),
  export: vi.fn(),
  template: vi.fn(),
  campaign: vi.fn(),
  parse: vi.fn(),
}));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/session", () => ({ requireUser: mocks.user }));
vi.mock("@/lib/rate-limit", async (original) => ({
  ...(await original<typeof import("@/lib/rate-limit")>()),
  consumeBudgets: mocks.limit,
}));
vi.mock("@/lib/account", () => ({ exportAccount: mocks.export }));
vi.mock("@/lib/db", () => ({
  db: { template: { findFirst: mocks.template } },
}));
vi.mock("@/lib/campaigns", () => ({ createCampaign: mocks.campaign }));
vi.mock("@/lib/inngest", () => ({ dispatchPending: vi.fn() }));
vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
import { RateLimitError, RateLimitUnavailable } from "@/lib/rate-limit";
import { GET as accountExport } from "@/app/api/account/export/route";
import { GET as templateExport } from "@/app/api/templates/[id]/export/route";
import { submitCampaign, importContacts } from "@/lib/actions";
const owner = "11111111-1111-4111-8111-111111111111";
beforeEach(() => {
  vi.resetAllMocks();
  mocks.auth.mockResolvedValue({ user: { id: owner } });
  mocks.user.mockResolvedValue({ id: owner });
});
describe("hardening boundaries", () => {
  it("authenticates exports before charging and scopes both to the shared budget", async () => {
    mocks.auth.mockResolvedValueOnce(null);
    expect((await accountExport()).status).toBe(401);
    expect(mocks.limit).not.toHaveBeenCalled();
    mocks.export.mockResolvedValue({});
    mocks.template.mockResolvedValue(null);
    await accountExport();
    await templateExport(new Request("http://localhost"), {
      params: Promise.resolve({ id: owner }),
    });
    expect(mocks.limit.mock.calls).toEqual([
      [owner, ["export"]],
      [owner, ["export"]],
    ]);
  });
  it.each([new RateLimitError(3600), new RateLimitUnavailable()])(
    "blocks export data work when admission fails",
    async (error) => {
      mocks.limit.mockRejectedValue(error);
      for (const response of [
        await accountExport(),
        await templateExport(new Request("http://localhost"), {
          params: Promise.resolve({ id: owner }),
        }),
      ]) {
        expect(response.status).toBe(
          error instanceof RateLimitError ? 429 : 503,
        );
        if (error instanceof RateLimitError)
          expect(response.headers.get("Retry-After")).toBe("3600");
      }
      expect(mocks.export).not.toHaveBeenCalled();
      expect(mocks.template).not.toHaveBeenCalled();
    },
  );
  it("returns stable action rate-limit codes and delays before business parsing", async () => {
    mocks.limit.mockRejectedValue(new RateLimitError(123));
    expect(await submitCampaign({})).toMatchObject({
      ok: false,
      code: "RATE_LIMITED",
      retryAfter: 123,
    });
    expect(
      await importContacts({
        get secret() {
          throw new Error("must not inspect");
        },
      }),
    ).toMatchObject({ ok: false, code: "RATE_LIMITED", retryAfter: 123 });
    expect(mocks.campaign).not.toHaveBeenCalled();
    expect(mocks.limit.mock.calls).toEqual([
      [owner, ["campaign"]],
      [owner, ["csv"]],
    ]);
  });
});
